target.css:
:root {
  --ink: #263343;
  --paper: #fffdf6;
  --coral: #ef725b;
  --mist: #dbe8e6;
  --muted: #68757b;
}

.transfer {
  width: 460px;
  display: flex;
  overflow: hidden;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
}

.ticket-main {
  flex: 1;
  padding: 16px 18px;
}

.ticket-head {
  display: flex;
  justify-content: space-between;
  margin-bottom: 9px;
}

.kicker,
.date {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.transfer h1 {
  margin: 0 0 14px;
  color: var(--ink);
  font-size: 22px;
  line-height: 1;
}

.route {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--ink);
  font-size: 13px;
  font-weight: 700;
}

.line {
  flex: 1;
  height: 2px;
  background: var(--coral);
}

.route-code {
  width: 92px;
  display: grid;
  place-items: center;
  background: var(--mist);
  border-left: 2px dashed var(--ink);
  color: var(--coral);
  font-size: 30px;
  font-weight: 800;
}
